import{P as g,I as c,g as d,j as m,d as e,k as n,F as x,N as C,x as z,V as p,l as h,ae as f,b as M,M as u,c as q}from"./chunks/framework.CjoWWfVe.js";const _={class:"custom-section section-dark-1 showcase-section-visible"},P={class:"section-container"},T={class:"showcase-interactive"},F={class:"showcase-nav"},S=["onClick"],B={class:"tab-content"},O={class:"tab-title"},R={class:"tab-desc"},A={class:"showcase-display"},j={class:"window-header"},I={class:"window-title"},E={class:"window-body"},V=["src","alt"],N=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"OmniCraft ERP","text":"Order in business. Control over personal capital.","tagline":"Accounting software for independent artisans, craft workshops, and other manufacturers. Adapts flexibly to your needs: track businesses, personal finances, and life goals. Use convenient mixed accounting without separating personal and business funds—no routine transfers. Or assign dedicated accounts to each project for classic separated control.","image":{"src":"/logo.svg","alt":"OmniCraft ERP Logo"},"actions":[{"theme":"brand","text":"Download for Windows ↓","link":"https://github.com/NikMurashkin/OmniCraft-ERP-Releases/releases/latest/download/OmniCraft_ERP.exe"},{"theme":"alt","text":"Read Documentation →","link":"/docs/introduction"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),D={name:"index.md"},L=Object.assign(D,{setup(G){const r=u(!1),v=u(0),t=[{title:"Workshop",desc:"Equipment and tool tracking with automatic depreciation calculation.",image:"/ru/dark/workshop.webp"},{title:"Raw Materials",desc:"Inventory management with Moving Average Cost (MAC) and shipping allocation.",image:"/ru/dark/raw_materials.webp"},{title:"Batch Calculator",desc:"Calculate batch costs and adequate material deficit on the warehouse.",image:"/ru/dark/calculator_batch_calculator.webp"},{title:"Recipe Database",desc:"Create technological cards calculating materials and labor time.",image:"/ru/dark/calculator_recipe_database.webp"},{title:"Production Workbench",desc:"Manage manufacturing queue with dynamic materials reservation.",image:"/ru/dark/production.webp"},{title:"Finished Goods",desc:"Track ready-to-sell stock using FIFO and perform inventory audits.",image:"/ru/dark/finished_goods.webp"},{title:"Sales",desc:"POS terminal, tracking channels, payment commissions, and delivery costs.",image:"/ru/dark/sales.webp"},{title:"Cash Flow (DDS)",desc:"Journal of cash inflows and outflows, operating expenses, and taxes.",image:"/ru/dark/cash_flow.webp"},{title:"Capital (Balance)",desc:"Managerial balance sheet of the workshop and net worth of your business.",image:"/ru/dark/capital.webp"},{title:"Analytics",desc:"KPIs, break-even point, and time ROI of your labor.",image:"/ru/dark/analytics.webp"},{title:"Workspaces",desc:"Manage independent businesses and track global personal capital.",image:"/ru/dark/spaces.webp"}],w=q(()=>t.map(s=>({image:s.image,title:s.title,description:s.desc}))),y=s=>{v.value=s,r.value=!0},a=u(0);return(s,i)=>{const k=g("ImageGallery"),b=g("ClientOnly");return c(),d("div",null,[i[8]||(i[8]=m('<div class="custom-section section-dark-2"><div class="section-container"><div class="section-header audience-section-header"><h2 class="gradient-text">Who is this software for</h2></div><div class="audience-grid"><div class="audience-card"><div class="audience-card-header"><div class="audience-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path><polyline points="3.27 6.96 12 12.01 20.73 6.96"></polyline><line x1="12" y1="22.08" x2="12" y2="12"></line></svg></div><span class="version-badge basic">Basic version</span></div><h3>Production tracking only</h3><div class="audience-text"><p>The program is perfectly suited for artisans and workshops creating physical products—whether it&#39;s leathercraft, woodworking, ceramics, metalworking, or absolutely any other craft.</p><p>You get strict control over the entire production cycle: from purchasing raw materials and automatically calculating the honest cost of items to managing the queue of orders on the workbench and the finished goods warehouse.</p></div></div><div class="audience-card pro-audience"><div class="pro-glow-bg"></div><div class="audience-card-header audience-card-header-pro"><div class="audience-icon pro-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 2 7 12 12 22 7 12 2"></polygon><polyline points="2 17 12 22 22 17"></polyline><polyline points="2 12 12 17 22 12"></polyline></svg></div><span class="version-badge pro">PRO version required</span></div><h3 class="audience-pro-title">Comprehensive business &amp; life tracking</h3><div class="audience-text audience-pro-text"><p>For those running multiple projects simultaneously. The system allows creating separate isolated workspaces not only for production, but also for retail, services, education, or simply tracking hobby expenses.</p><p>Here you can also log important personal expenses, plan directions, and set goals for personal efficiency. The program will merge data from all your businesses, accounts, and assets into the global <strong>&quot;My Capital&quot;</strong> workspace, tracking the change in your wealth dynamically.</p></div></div></div></div></div>',1)),e("div",_,[e("div",P,[i[7]||(i[7]=e("div",{class:"section-header"},[e("h2",{class:"gradient-text"},"Interface in detail"),e("p",{class:"section-subtitle"},[n("OmniCraft ERP adapts to different workflows. Let's see how a full accounting cycle looks "),e("span",{class:"highlight-badge"},[n("on the example of a "),e("strong",null,"Production"),n(" workspace")]),n(". Select tabs to explore the system's capabilities.")])],-1)),e("div",T,[e("div",F,[(c(),d(x,null,C(t,(o,l)=>e("div",{key:l,class:z(["showcase-tab",{active:a.value===l}]),onClick:W=>a.value=l},[i[2]||(i[2]=e("div",{class:"tab-indicator"},null,-1)),e("div",B,[e("div",O,p(o.title),1),e("div",R,p(o.desc),1)])],10,S)),64))]),e("div",A,[i[6]||(i[6]=e("div",{class:"display-glow"},null,-1)),e("div",{class:"app-window",onClick:i[0]||(i[0]=o=>y(a.value))},[e("div",j,[i[3]||(i[3]=e("div",{class:"dot red"},null,-1)),i[4]||(i[4]=e("div",{class:"dot yellow"},null,-1)),i[5]||(i[5]=e("div",{class:"dot green"},null,-1)),e("div",I,p(t[a.value].title)+" — OmniCraft ERP",1)]),e("div",E,[h(M,{name:"fade",mode:"out-in"},{default:f(()=>[(c(),d("img",{key:a.value,src:t[a.value].image,alt:t[a.value].title,class:"ui-screenshot"},null,8,V))]),_:1})])])])])])]),h(b,null,{default:f(()=>[h(k,{isOpen:r.value,items:w.value,initialIndex:v.value,onClose:i[1]||(i[1]=o=>r.value=!1)},null,8,["isOpen","items","initialIndex"])]),_:1}),i[9]||(i[9]=m('<div class="custom-section section-dark-1"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Fundamental problems we solved</h2><p class="section-subtitle">Whether you run a single craft workshop or manage multiple businesses, the system eliminates major management mistakes and operational friction.</p></div><div class="timeline-group"><h3>Automation and eliminating routine</h3><p>Freedom from manual calculations and routine spreadsheets</p></div><div class="zigzag-timeline"><div class="zigzag-row"><div class="zigzag-thesis"><h3>End-to-end operations and error protection</h3><span class="thesis-icon"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#60a5fa" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><path d="m9 15 2 2 4-4"></path></svg></span></div><div class="zigzag-dot"></div><div class="zigzag-content"><p>The accounting process is organized as a strict end-to-end pipeline. A single click to complete a stage automatically deducts the used raw materials, credits the finished product to the showcase, and locks in its actual cost price, reliably protecting data from accidental errors.</p></div></div><div class="zigzag-row"><div class="zigzag-thesis"><h3>Smart cost allocation without a calculator</h3><span class="thesis-icon"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#a78bfa" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><rect width="16" height="20" x="4" y="2" rx="2"></rect><line x1="8" x2="16" y1="6" y2="6"></line><line x1="16" x2="16" y1="14" y2="18"></line><path d="M16 10h.01"></path><path d="M12 10h.01"></path><path d="M8 10h.01"></path><path d="M12 14h.01"></path><path d="M8 14h.01"></path><path d="M12 18h.01"></path><path d="M8 18h.01"></path></svg></span></div><div class="zigzag-dot"></div><div class="zigzag-content"><p>You don&#39;t need to be an accountant. The program automatically calculates the Moving Average Cost (MAC) of materials with each new purchase, allocates logistics costs, and helps evaluate equipment wear (from hand tools to CNC machines) for precise overhead planning.</p></div></div><div class="zigzag-row"><div class="zigzag-thesis"><h3>No more surprises at the workbench</h3><span class="thesis-icon"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#fb923c" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="m7.5 4.27 9 5.15"></path><path d="M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z"></path><path d="m3.3 7 8.7 5 8.7-5"></path><path d="M12 22V12"></path></svg></span></div><div class="zigzag-dot"></div><div class="zigzag-content"><p>You will see a material deficit warning even before you start an order or take an advance payment. The dynamic queue automatically reserves the necessary hardware, wood, or specific chemicals in the warehouse based on task priority.</p></div></div></div><div class="timeline-group"><h3>Honest finances and clear analytics</h3><p>Efficient and effortless control</p></div><div class="zigzag-timeline"><div class="zigzag-row"><div class="zigzag-thesis"><h3>Eliminating the &quot;Illusion of Profit&quot;</h3><span class="thesis-icon"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#f87171" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"></polyline><polyline points="16 7 22 7 22 13"></polyline></svg></span></div><div class="zigzag-dot"></div><div class="zigzag-content"><p>The difference between the sale price and the cost of the main material is not net profit. The calculator will help combine all costs: raw materials, overheads (equipment depreciation, rent, consumables), defect rate, and the price of your working hours, revealing the real, honest net profit of each item.</p></div></div><div class="zigzag-row"><div class="zigzag-thesis"><h3>Net profit per hour of work</h3><span class="thesis-icon"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#34d399" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span></div><div class="zigzag-dot"></div><div class="zigzag-content"><p>The Time ROI ranking visually shows that mass-producing candles yields $30/hr, while creating a complex custom piece yields only $5/hr. This is a precise mathematical signal to revise prices or optimize your product range.</p></div></div><div class="zigzag-row"><div class="zigzag-thesis"><h3>Focused business analytics</h3><span class="thesis-icon"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#38bdf8" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><line x1="12" x2="12" y1="20" y2="10"></line><line x1="18" x2="18" y1="20" y2="4"></line><line x1="6" x2="6" y1="20" y2="16"></line></svg></span></div><div class="zigzag-dot"></div><div class="zigzag-content"><p>You have access to deep, detailed analytics. The program provides general analytics and useful data on individual workflow tabs. Each metric holds logical value, covering both core and important supplementary parameters of your business, excluding unsystematic data to avoid turning analytics into chaos.</p></div></div><div class="zigzag-row"><div class="zigzag-thesis"><h3>Protecting old batches from depreciation</h3><span class="thesis-icon"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#facc15" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2H2v10l9.29 9.29c.94.94 2.48.94 3.42 0l6.58-6.58c.94-.94.94-2.48 0-3.42L12 2Z"></path><path d="M7 7h.01"></path></svg></span></div><div class="zigzag-dot"></div><div class="zigzag-content"><p>Even if suppliers double raw material prices tomorrow, the program will write off the sold old item from the shelf at its original, historically accurate cost (FIFO method). Your profit in financial reports will always be calculated with pinpoint precision.</p></div></div></div><div class="timeline-footer"><h3>And much more...</h3><p>OmniCraft ERP capabilities go beyond simple production tracking. The system allows inventory audits without distorting Cash Flow (DDS) reports, distributing logistics costs (choosing between client payment or workshop expense), flexible pricing for different sales channels, and maintaining a structured Cash Flow register for tax calculation.</p></div></div></div><div class="custom-section section-dark-2 pro-section"><div class="section-container"><div class="section-header"><span class="pro-kicker">✨ The PRO Ecosystem</span><h2 class="pro-heading">What&#39;s beyond Production?</h2><p class="section-subtitle">The base <strong>&quot;Standard&quot;</strong> version perfectly covers the needs of a single craft business. But if you think like an entrepreneur, the <strong>PRO</strong> version lets you deploy separate isolated workspaces for each direction and unite them into global capital.</p></div><div class="bento-grid profiles-grid mb-12"><div class="bento-card profile-card active-profile"><div class="profile-icon-wrapper icon-blue"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M2 20a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V8l-7 5V8l-7 5V4a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2Z"></path><path d="M17 18h1"></path><path d="M12 18h1"></path><path d="M7 18h1"></path></svg></div><h3>Production</h3><p>Full cycle: raw material purchasing (MAC), calculation, workbench, material reservation, and finished goods warehouse.</p></div><div class="bento-card profile-card"><div class="profile-icon-wrapper icon-purple"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"></path></svg></div><h3>Services / Custom <span class="coming-soon-badge">Soon</span></h3><p>For individual orders, restoration, or design. Track your invested time without tying it to a rigid showcase warehouse.</p></div><div class="bento-card profile-card"><div class="profile-icon-wrapper icon-orange"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M3 9h18v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V9Z"></path><path d="m3 9 2.45-4.9A2 2 0 0 1 7.24 3h9.52a2 2 0 0 1 1.8 1.1L21 9"></path><path d="M12 3v6"></path></svg></div><h3>Trade / Retail <span class="coming-soon-badge">Soon</span></h3><p>Direct purchases and resale of finished goods, tools, or chemicals. Track wholesale batches without a production pipeline.</p></div><div class="bento-card profile-card"><div class="profile-icon-wrapper icon-pink"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect width="20" height="14" x="2" y="3" rx="2"></rect><line x1="8" x2="16" y1="21" y2="21"></line><line x1="12" x2="12" y1="17" y2="21"></line></svg></div><h3>Education / Digital <span class="coming-soon-badge">Soon</span></h3><p>Selling proprietary digital patterns, video tutorials, or hosting live masterclasses. Pure margin without physical raw materials.</p></div><div class="bento-card profile-card"><div class="profile-icon-wrapper icon-teal"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="13.5" cy="6.5" r=".5" fill="currentColor"></circle><circle cx="17.5" cy="10.5" r=".5" fill="currentColor"></circle><circle cx="8.5" cy="7.5" r=".5" fill="currentColor"></circle><circle cx="6.5" cy="12.5" r=".5" fill="currentColor"></circle><path d="M12 2C6.5 2 2 6.5 2 12s4.5 10 10 10c.926 0 1.648-.746 1.648-1.688 0-.437-.18-.835-.437-1.125-.29-.289-.438-.652-.438-1.125a1.64 1.64 0 0 1 1.668-1.668h1.996c3.051 0 5.555-2.503 5.555-5.554C21.965 6.012 17.461 2 12 2z"></path></svg></div><h3>Activities / Hobby <span class="coming-soon-badge">Soon</span></h3><p>A sandbox for hobbies (ceramics, gardening). Simply record material and equipment expenses to know how much your hobby costs.</p></div><div class="bento-card profile-card"><div class="profile-icon-wrapper icon-red"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><circle cx="12" cy="12" r="6"></circle><circle cx="12" cy="12" r="2"></circle></svg></div><h3>LYF (Goals) <span class="coming-soon-badge">Soon</span></h3><p>Workspace for Life, Yearly Goals, and Focus. Plan major purchases or set non-financial goals for personal development and efficiency.</p></div></div><div class="bento-grid pro-grid"><div class="bento-card span-full capital-card"><div class="capital-glow"></div><div class="capital-content capital-content-flex"><div class="capital-text-block"><div class="profile-icon-wrapper icon-green large-icon"><svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="5" width="20" height="14" rx="2"></rect><line x1="2" y1="10" x2="22" y2="10"></line></svg></div><h3 class="capital-title">Global Dashboard<br>&quot;My Capital&quot;</h3><p class="capital-desc"> The real magic of PRO mode. The program automatically aggregates net profit from all your businesses, adds the value of assets (apartments, cars), and actual balances on personal bank cards. </p></div><div class="capital-feature-card"><div class="capital-feature-glow"></div><h4 class="capital-feature-title"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#10B981" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z"></path><path d="m9 12 2 2 4-4"></path></svg> Hassle-Free Expense Tracking </h4><p class="capital-feature-desc"> You no longer need to type every cup of coffee or grocery purchase into a spreadsheet! By matching recorded incomes, major expenses, and actual card balances, the system itself will deduce the net balance of unrecorded daily transactions. This frees you from micromanagement, showing the real balance of your minor household expenses and random inflows. </p></div></div></div><div class="bento-card span-full modules-banner"><div class="profile-icon-wrapper icon-blue medium-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor"><path d="M20.5 11H19V7c0-1.1-.9-2-2-2h-4V3.5C13 2.12 11.88 1 10.5 1S8 2.12 8 3.5V5H4c-1.1 0-1.99.9-1.99 2v3.8H3.5c1.49 0 2.7 1.21 2.7 2.7s-1.21 2.7-2.7 2.7H2V20c0 1.1.9 2 2 2h3.8v-1.5c0-1.49 1.21-2.7 2.7-2.7 1.49 0 2.7 1.21 2.7 2.7V22H17c1.1 0 2-.9 2-2v-4h1.5c1.38 0 2.5-1.12 2.5-2.5S21.88 11 20.5 11z"></path></svg></div><div><h4 class="modules-title">Add-on Modules (Soon)</h4><p class="modules-desc">In future updates, the ecosystem will expand with plug-in modules (for example, a <strong>parametric pattern generation module for leathercrafters</strong>). You will be able to add only the tools you need to solve your specific production tasks. Modules are available in both Standard and PRO versions.</p></div></div></div></div></div><div class="custom-section section-dark-1"><div class="section-container"><div class="mixed-finance-banner"><div class="mixed-finance-glow left"></div><div class="mixed-finance-glow right"></div><div class="mixed-finance-content"><div class="mixed-finance-header"><div class="mixed-finance-icon"><svg width="52" height="52" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" class="mixed-finance-svg"><defs><linearGradient id="mixGrad1" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stop-color="#3B82F6"></stop><stop offset="100%" stop-color="#2563EB"></stop></linearGradient><linearGradient id="mixGrad2" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stop-color="#A594FD"></stop><stop offset="100%" stop-color="#7B61FF"></stop></linearGradient></defs><circle cx="8.5" cy="12" r="6.5" stroke="url(#mixGrad1)" stroke-width="2" fill="rgba(59, 130, 246, 0.15)"></circle><circle cx="15.5" cy="12" r="6.5" stroke="url(#mixGrad2)" stroke-width="2" fill="rgba(165, 148, 253, 0.15)"></circle><polyline points="3 16 9 10 13 13 21 5" stroke="#FFFFFF" stroke-width="2"></polyline><polyline points="17 5 21 5 21 9" stroke="#FFFFFF" stroke-width="2"></polyline></svg></div><div><h2 class="mixed-finance-title"> Accounting without bureaucracy:<br><span class="mixed-finance-highlight">Mixed Finances</span></h2></div></div><div class="mixed-finance-text-wrapper"><p class="mixed-finance-text"> By default, OmniCraft ERP is designed not to complicate your life. You <strong>do not need to open a separate bank account for business</strong> or make artificial transfers to yourself &quot;for living&quot;. Pay for materials from your personal card, and spend the revenue on household needs—the system will still show a crystal clear and accurate picture. </p></div><div class="mixed-finance-cards"><div class="mixed-finance-card"><h4 class="mixed-finance-card-title red"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"></path></svg> Cash Flow Balance </h4><p class="mixed-finance-card-desc">Shows how much personal funds you invested at the start and <strong>how much your business has already paid off</strong>.</p></div><div class="mixed-finance-card"><h4 class="mixed-finance-card-title green"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"></polyline><polyline points="16 7 22 7 22 13"></polyline></svg> Net Profit </h4><p class="mixed-finance-card-desc">Reflects the real <strong>operational efficiency</strong> of your workshop, regardless of where the money physically lies.</p></div><div class="mixed-finance-card"><h4 class="mixed-finance-card-title blue"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path><polyline points="3.27 6.96 12 12.01 20.73 6.96"></polyline><line x1="12" y1="22.08" x2="12" y2="12"></line></svg> Capital </h4><p class="mixed-finance-card-desc">Evaluates the <strong>current value of the business</strong>, carefully aggregating all your equipment, raw materials, and finished goods.</p></div></div><div class="mixed-finance-note"><p class="mixed-finance-note-text"><strong>System Flexibility:</strong> If over time you decide to fully separate personal and business finances, you won&#39;t have to change the program. At any moment, you can simply set up a separate account for the workshop, and the system will seamlessly support classic separated accounting. </p></div></div></div></div></div><div class="custom-section section-dark-2"><div class="section-container"><div class="bento-card span-full docs-banner"><div class="docs-left"><div class="docs-header"><div class="profile-icon-wrapper icon-blue custom-docs-icon"><svg xmlns="http://www.w3.org/2000/svg" width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"></path><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"></path></svg></div><h2 class="docs-title">Comprehensive Documentation</h2></div><p class="docs-desc"> OmniCraft ERP is not just a spreadsheet, but a professional tool with deep financial logic. We&#39;ve detailed every mechanism of the system so you can use its potential to 100%. <br><br> Learn how the production pipeline works, how MAC and FIFO methods protect your profit, how to transfer balances from old software, and correctly manage mixed finances. </p><a class="vp-button brand docs-btn" href="/docs/introduction"> Read the Guide <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div><div class="docs-right"><div class="docs-toc-card"><h4 class="docs-toc-title">Guide Contents:</h4><ul class="docs-toc-list"><li class="docs-toc-item"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="docs-toc-icon"><path d="M12 2S4.5 6 4.5 14.5c0 2 1 3.5 3 4.5V22l4.5-2 4.5 2v-3c2-1 3-2.5 3-4.5C19.5 6 12 2 12 2z"></path><circle cx="12" cy="11" r="2"></circle></svg><a href="/docs/getting-started" class="docs-toc-link">Quick Start &amp; Balance Transfer</a></li><li class="docs-toc-item"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="docs-toc-icon"><path d="M17 1l4 4-4 4"></path><path d="M3 11V9a4 4 0 0 1 4-4h14"></path><path d="M7 23l-4-4 4-4"></path><path d="M21 13v2a4 4 0 0 1-4 4H3"></path></svg><a href="/docs/accounting-logic" class="docs-toc-link">Accounting Logic: Production Pipeline</a></li><li class="docs-toc-item"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="docs-toc-icon"><path d="M2 4l3 12h14l3-12-6 6-4-6-6 6-4-6z"></path><rect x="3" y="18" width="18" height="2" rx="1"></rect></svg><a href="/docs/spaces/moy-kapital/pro-mode" class="docs-toc-link">PRO Mode: Personal Finances</a></li><li class="docs-toc-item"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="docs-toc-icon"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path></svg><a href="/docs/backups" class="docs-toc-link">Backups &amp; Security (GFS, WAL)</a></li></ul></div></div></div></div></div><div class="custom-section section-dark-2"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Transparent Licensing Model</h2><p class="section-subtitle">No monthly fees or hidden costs. Pay only for the scale you actually need.</p></div><div class="sleek-pricing"><div class="pricing-card"><div class="p-header"><h4>Free (Trial)</h4><p>To test and prototype</p></div><div class="p-price"><div class="price-row"><span class="price-val">$0</span></div></div><ul class="p-features"><li><i></i>All accounting features of &quot;Standard&quot;</li><li class="warning"><i></i>Limit: up to 20 receipts (sales)</li><li class="disabled"><i></i>Add-on modules unavailable</li></ul></div><div class="pricing-card standard"><div class="p-header"><h4>Standard</h4><p>Essential tool for workshops</p></div><div class="p-price"><div class="price-row"><span class="price-val">$2.90</span><span class="price-period">/ mo</span></div><div class="price-or">or</div><div class="price-row"><span class="price-val">$74.90</span><span class="price-period">lifetime</span></div></div><ul class="p-features"><li class="active"><i></i><strong>Unlimited sales entries</strong></li><li><i></i>Full operational pipeline</li><li><i></i>WAL safety &amp; auto GFS backups</li><li><i></i>Subscription or lifetime options</li></ul></div><div class="pricing-card pro-card pricing-card-bg-pad"><div class="pro-glow"></div><div class="pro-badge">PRO Mode</div><div class="p-header"><h4>PRO Extension</h4><p>Complete business suite</p></div><div class="p-price"><div class="price-row"><span class="price-val">$44.90</span><span class="price-period">lifetime</span></div></div><ul class="p-features"><li class="active-pro"><i></i><strong>&quot;My Capital&quot; global hub</strong></li><li class="active-pro"><i></i><strong>Multi-workspaces support</strong></li><li class="active-pro"><i></i><strong>Aggregated backup packaging</strong></li><li><i></i>One-time upgrade (lifetime)</li></ul></div></div><div class="pricing-pre-notice"><p><strong>Important notice about PRO license:</strong> To fully operate the program, an active Standard license is required (monthly subscription or one-time purchase for unlimited time), after which the program can be upgraded to the PRO version. The PRO version will work only if the Standard license is activated (no matter which one—subscription or perpetual).</p><p><strong>Device usage:</strong> The commercial license can be used simultaneously on up to 5 devices. The list of active devices can be easily managed on the <a href="/docs/buy-license">license purchase page</a> (using a simple management form). If any device fails, you can easily delete it from the list and bind a new one.</p></div><div class="pricing-action-wrapper"><a class="vp-button brand pricing-action-btn" href="/docs/buy-license"> Buy (or upgrade) a license </a></div><div class="pricing-notice with-margin"><strong>Specialized Add-ons (modules):</strong> Niche tools for specific tasks are paid for once and separately. You never pay for features you do not use. Modules are available for both Standard and PRO licenses. </div></div></div><div class="custom-section section-dark-1"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Frequently Asked Questions</h2></div><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">I keep records in Excel. Is it hard to switch to OmniCraft ERP?</summary><div class="faq-content"><p>The transition takes minimal time. You don&#39;t need to transfer your entire history of old sales. Simply use the &quot;estimated starting point&quot; approach: enter your current equipment into the Workshop, <strong>making sure to mark it as a &quot;Gratuitous receipt&quot;</strong> (so the program doesn&#39;t deduct funds from Cash Flow again, as these expenses were already accounted for in the past), add the actual raw material balances to the Warehouse, and perform a special starting corrective operation to lock in the historical Cash Flow balance and debts. Read more about migrating in the <a class="faq-link" href="/docs/getting-started">Quick Start</a> section.</p></div></details><details class="faq-item"><summary class="faq-summary">What happens if my computer breaks?</summary><div class="faq-content"><p>Built-in shadow copies (GFS) protect data from sudden power outages, but in the event of a physical drive failure, they will perish along with it. Therefore, we strongly recommend regularly exporting the database manually to a flash drive or the cloud. When moving to a new PC, install the program and import the saved file. The license will need to be restored on a special license management page on the website: since it binds to the hardware, you will need to reset the old binding by entering your license token. The license key supports simultaneous use on <strong>up to 5 devices</strong>, and you can independently remove old devices from the list and bind new ones.</p></div></details><details class="faq-item"><summary class="faq-summary">Is there a version for Mac OS, Linux, or Android?</summary><div class="faq-content"><p>Currently, official installation packages are built only for Windows OS. However, the system core is designed to be fully cross-platform. The development and release of native versions for Mac OS, Linux, as well as a mobile app for Android, are planned in future updates.</p></div></details><details class="faq-item"><summary class="faq-summary">Can I work with the database from different computers?</summary><div class="faq-content"><p>OmniCraft ERP is designed as a local standalone system for maximum protection of commercial secrets; there is currently no direct online synchronization. In the future, we plan to implement full-fledged cloud data synchronization for seamless collaborative work across different devices.</p></div></details><details class="faq-item"><summary class="faq-summary">What happens when the 20-sale limit runs out in the free version?</summary><div class="faq-content"><p>The program will block sales processing. Meanwhile, all other features remain fully accessible: you can freely add new materials, enter tools and machines into the Workshop, create or edit recipes, populate directories, and analyze past periods. Upon activating a purchased license key, all restrictions will be lifted instantly, and your accumulated history will remain intact.</p></div></details><details class="faq-item"><summary class="faq-summary">Can I track multiple different projects in one program?</summary><div class="faq-content"><p>In the basic &quot;Standard&quot; version, all accounting is conducted within a single production setup. If you have multiple directions (e.g., leather production and a separate hardware store), you will need to upgrade to the PRO mode. It allows creating isolated &quot;Multi-workspaces&quot; with separate warehouses and Cash Flow, aggregating their total profit in the global &quot;My Capital&quot; workspace.</p></div></details><details class="faq-item"><summary class="faq-summary">Do I need to pay for software updates when buying a lifetime license?</summary><div class="faq-content"><p>No, when purchasing a perpetual lifetime license, all subsequent system updates, interface improvements, and bug fixes within your tier are provided absolutely free. The built-in auto-updater will prompt you to install the new version and migrate your database automatically. Only the upgrade to the PRO version and specialized add-on modules are paid separately.</p></div></details></div></div></div><div class="custom-cta-block cta-centered"><div class="cta-icon-wrapper"><svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3c-1.2 0-3.5.5-5 1.5C5 5.8 4 8 4 10.5c0 3 1.5 6.5 4 8.5l4 2 4-2c2.5-2 4-5.5 4-8.5 0-2.5-1-4.7-3-6C15.5 3.5 13.2 3 12 3z" stroke="var(--vp-c-brand)"></path><path d="M7 14s2-3 5-3 5 3 5 3" stroke="#A594FD"></path><path d="M12 7V17M12 7L9 11M12 7l3 4" stroke="var(--vp-c-brand)"></path></svg></div><h2 class="gradient-text cta-title">Designed in a workshop.<br>Built for business-minded artisans.</h2><p class="cta-text"> This program was born not in faceless offices, but on the real workbench of our leathercraft workshop. Every algorithm—from cascading material reserves to equipment depreciation—is designed based on personal artisanal experience. We know the ins and outs of production and the daily pains of a maker from the inside. </p><div class="cta-buttons cta-buttons-spaced"><a class="vp-button brand" href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases/releases/latest/download/OmniCraft_ERP.exe">⬇ Download for Windows</a><a class="vp-button alt" href="/docs/introduction">Read Documentation</a></div><div class="footer-links"><a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank">Project Repository</a><a href="/docs/terms#payment-delivery-returns">Payment, Delivery &amp; Returns</a><a href="/docs/about">About the Developers</a><a href="/docs/contacts">Contacts &amp; Details</a></div></div>',7))])}}});export{N as __pageData,L as default};
